    /// <summary>
    /// 部品・モデルのメッシュの外形（Unity のローカル座標、拡大 1、原点 = 部品の底の中心）。斜面の接地（GroundFit）が足元の向きのある長方形に使う。
    /// tools/preview と同じ取り込み（Blender の FBX 取り込み → Unity の軸 x, y = 上, z）で測った値：{ 半幅 X, 底 Y, 上 Y, 半幅 Z }
    /// （X・Z は原点から遠い側の絶対値）。無い部品は DressingPlan.SizeOf の円で代用する。
    /// </summary>
    public static class PartBounds
    {
        public struct Box
        {
            public float hx, y0, y1, hz;
        }

        public static bool TryGet(string asset, string part, out Box b)
        {
            float[] v;
            if (T.TryGetValue(asset + "|" + (part ?? ""), out v)) { b = new Box { hx = v[0], y0 = v[1], y1 = v[2], hz = v[3] }; return true; }
            b = default(Box);
            return false;
        }

        public static int Count => T.Count;

